view.template:
{% load view_tags %}
{% get_set 'project/partner/id' as partners %}
{% get_value 'project/title' as title %}
{% get_value 'project/schedule/project_end' as release_date %}
{% get_values 'smp/software-pid' as software_pids %}
{% get_values 'smp/software-license' as software_licenses %}

cff-version: 1.2.0<br>
message: "If you use this software, please cite it as below."<br>
authors:
<ul>
{% for p in partners %}
{% get_set_value p 'project/partner/family-name' as p_family_name %}
{% get_set_value p 'project/partner/given-name' as p_given_name %}
{% get_set_value p 'project/partner/orcid-id' as p_orcid_id %}
{% get_values 'project/partner/affiliation' forloop.counter0 as p_affiliations %}
<li>family-names: {% if p_family_name.value %}"{{ p_family_name.value }}"{% endif %}<br>
given-names: {% if p_given_name.value %}"{{ p_given_name.value }}"{% endif %}<br>
{% if p_orcid_id.value %}orcid: "{{ p_orcid_id.value }}"<br>{% endif %}
{% if p_affiliations %}affiliation: "{% for a in p_affiliations %}{{ a.value }}{% if not forloop.last %} & {% endif %}{% endfor %}"{% endif %}
</li>
{% endfor %}
</ul>
title: "{{ title.value }}"<br>
type: software<br>

{# ## IDENTIFIERS ## #}

{% if software_pids|length == 1 %}
{% if software_pids.0.option_text == 'DOI' or software_pids.0.option_text == 'URL' %}
  {{ software_pids.0.option_text|lower }}: {{ software_pids.0.text }}
{% endif %}
{% endif %}

{% if software_pids|length == 1 and software_pids.0.option_text != "DOI" and software_pids.0.option_text != "URL" %}
identifiers:
<ul>
<li>type: {% if software_pids.0.option_text == "Software Heritage Identifier"  %}swh{% else %}{{ software_pids.0.option_text|lower }}{% endif %}<br>
value: {{ software_pids.0.text }}<br>
</li>
</ul>
{% endif %}

{% if software_pids|length > 1 %}
identifiers:
<ul>
  {% for sp in software_pids %}
    <li>type: {% if sp.option_text == "Software Heritage Identifier" %}swh{% else %}{{ sp.option_text|lower }}{% endif %}<br>
    value: {{ sp.text }}<br>
    </li>
  {% endfor %}
</ul>
{% endif %}

{# ################# #}

{# ## LICENSE ## #}

license: {% if software_licenses|length == 1 %}{% if software_licenses.0.text %}{{ software_licenses.0.text }}{% else %}{{ software_licenses.0.option_text }}{% endif %}
{% elif software_licenses|length > 1 %}
<ul>
  {% for sl in software_licenses %}
    <li>{% if sl.text %}{{ sl.text }}{% else %}{{ sl.option_text }}{% endif %}</li>
  {% endfor %}
</ul>
{% endif %}
</p>

{# ############# #}


date-released: {{ release_date.value|date:"Y-m-d" }}
